import{H as e,at as t,it as n,vt as r}from"./chunks/framework.dmHZ7NHG.js";var i=JSON.parse(`{"title":"Privacy","description":"Privacy by design in uuidna — no storage without consent, a stateless loopback-only daemon, client-side computation, nothing sent. Honest scope, not a claim of legal compliance.","frontmatter":{"title":"Privacy","description":"Privacy by design in uuidna — no storage without consent, a stateless loopback-only daemon, client-side computation, nothing sent. Honest scope, not a claim of legal compliance."},"headers":[],"relativePath":"docs/privacy.md","filePath":"docs/privacy.md"}`),a={name:`docs/privacy.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="privacy-by-design" tabindex="-1">Privacy by design <a class="header-anchor" href="#privacy-by-design" aria-label="Permalink to “Privacy by design”">​</a></h1><p>uuidna is built to respect privacy in its <strong>design</strong>, and to say plainly what it does and does not claim. This page is the honest account: the properties are real and checkable; the compliance is <strong>not</strong> asserted.</p><h2 id="what-uuidna-does" tabindex="-1">What uuidna does <a class="header-anchor" href="#what-uuidna-does" aria-label="Permalink to “What uuidna does”">​</a></h2><ul><li><strong>No storage without consent.</strong> Without an explicit, consent-gated opt-in, nothing you enter is stored. The default is to compute and return, not to keep.</li><li><strong>The daemon is loopback-only, read-only, and stateless.</strong> It binds to <code>127.0.0.1</code> (never a public interface), serves only reads, keeps nothing between requests, and logs no request bodies.</li><li><strong>Client-side by default.</strong> The site&#39;s tools — the reflector, the book audit, the message stream — compute in your browser. The data you choose stays on your machine; it is not sent to a server to be addressed.</li><li><strong>A content-address is of data you chose.</strong> <code>toUuid(x)</code> is computed from the value you hand it, on demand; it is a fingerprint, not a copy, and it is not transmitted anywhere by the act of computing it.</li><li><strong>No tracking.</strong> The pages are static; there is no analytics profiling and no advertising identifier riding along.</li></ul><h2 id="what-uuidna-does-not-claim" tabindex="-1">What uuidna does NOT claim <a class="header-anchor" href="#what-uuidna-does-not-claim" aria-label="Permalink to “What uuidna does NOT claim”">​</a></h2><ul><li><strong>This is privacy by <em>design</em>, not certified compliance.</strong> uuidna does <strong>not</strong> claim that all privacy laws are met, and it is <strong>not</strong> a statement that any specific regulation — GDPR, CCPA, or another — is satisfied. Compliance is a matter for counsel and audit, and a content-address cannot certify it. uuidna&#39;s own honesty gate <strong>refuses</strong> the claim &quot;all privacy laws are met&quot; as unbacked — the same gate it holds every other claim to.</li><li><strong>The design aligns with the <em>spirit</em>, not a certificate.</strong> Data minimisation, consent, and transparency are the principles above; alignment in spirit is not a legal guarantee, and this page does not pretend it is.</li><li><strong>You run it, you own the obligations.</strong> If you deploy or embed uuidna, the privacy obligations of <em>your</em> deployment are yours to meet with your own counsel; nothing here transfers them or discharges them.</li></ul><h2 id="trials-by-design-are-human" tabindex="-1">Trials, by design, are human <a class="header-anchor" href="#trials-by-design-are-human" aria-label="Permalink to “Trials, by design, are human”">​</a></h2><p>The trial is built <strong>for human judgment, not to replace it.</strong> It produces a <strong>recomputable</strong> verdict and a recheckable <a href="/trials">evidence bundle</a> — so a person does not have to <em>trust</em> it, they <strong>recompute</strong> it, and then <strong>they</strong> decide. A machine can settle whether a claim is backed and recomputable; whether to <em>act</em> is a human&#39;s, and a court&#39;s, ruling — never a fold&#39;s. The flag is always on the claim, never on the person. That is what &quot;integrity, not truth&quot; means in practice: uuidna hands a human something they can check for themselves, and leaves the deciding to them.</p><p><a href="/trials">The trial charter</a> · <a href="/license">License</a> · <a href="/captain/config">The contract &amp; consent</a></p>`,9)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};